def makePricev(stockCode,startDate=None):
	global allData
	info=allData[stockCode]
	strt=0
	if startDate:
		strt=info["dates"].find(startDate) # e.g. "2007/10/30"
		if strt<0: strt=0
	print("startDate =",info["dates"][strt],)
	return [[info["最低價"][i],info["最高價"][i],info["dates"][i],] for i in range(strt,len(info["dates"]))]
	pass


