def simStrategy(pricev,rsvRate=Decimal('0.3'),inflationPerDay=Decimal('1.0004'),transectionFeeRate_buy=Decimal('1.001'),transectionFeeRate_sell=Decimal('1.002')):
	rtv=[1]
	refValue=1-rsvRate
	shares=refValue/Decimal(pricev[0][1])
	ths0=1/Decimal('1.05'),Decimal('1.05'),
	refAdjs0=Decimal('0.9875'),1/Decimal('0.9875'),
	sharesRatioChangeTo_priceGoUp=1-Decimal('0.0375')
	acts0=1/sharesRatioChangeTo_priceGoUp-1,sharesRatioChangeTo_priceGoUp-1,
	cash=rsvRate
	cnt=1
	for day in range(1,len(pricev)):
		refValue*=inflationPerDay
		ths=ths0[0]*refValue,ths0[1]*refValue,
		vals=shares*Decimal(pricev[day][0]),shares*Decimal(pricev[day][1]),
		sharesD=0
		isAdjs=[False,False]
		if vals[0]<=ths[0] and 0<cash:
			isAdjs[0]=True
			p=min(ths[0]/shares,Decimal(pricev[day][1]))
			delta=min(cash/p,shares*acts0[0])
			sharesD+=delta # share inc.
			cash-=delta*p
			if cash<0: cash=0 # handle precision error
			cnt+=1
		if vals[1]>=ths[1]:
			isAdjs[1]=True
			p=max(ths[0]/shares,Decimal(pricev[day][0]))
			delta=max(-shares,shares*acts0[1])
			sharesD+=delta
			cash-=delta*p # cash inc.
			cnt+=1
		shares+=sharesD
		if isAdjs[0]!=isAdjs[1]:
			if isAdjs[0]: refValue*=refAdjs0[0]
			if isAdjs[1]: refValue*=refAdjs0[1]
		rtv.append(shares*Decimal(pricev[day][0])+cash)
		pass
	return cnt,[ [rtv[i],rtv[i],pricev[i][2],] for i in range(len(rtv)) ],


